const resolveProjectOrg = `-- name: ResolveProjectOrg :one

SELECT org_id FROM projects WHERE id = $1
`

// ---- Projects in an organisation ------------------------------------------
// tenant: system - the authorization step that finds a project's
// organisation before anything is checked against it.
func (q *Queries) ResolveProjectOrg(ctx context.Context, id uuid.UUID) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, resolveProjectOrg, id)
	var org_id uuid.UUID
	err := row.Scan(&org_id)
	return org_id, err
}

