const upsertProjectDBUser = `-- name: UpsertProjectDBUser :one
INSERT INTO project_db_users (project_id, user_id, org_id, role_name, scram_verifier, access)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (project_id, user_id) DO UPDATE
  SET scram_verifier = EXCLUDED.scram_verifier, access = EXCLUDED.access, rotated_at = now()
RETURNING project_id, user_id, org_id, role_name, scram_verifier, access, created_at, rotated_at
`

type UpsertProjectDBUserParams struct {
	ProjectID     uuid.UUID
	UserID        uuid.UUID
	OrgID         uuid.UUID
	RoleName      string
	ScramVerifier string
	Access        string
}

func (q *Queries) UpsertProjectDBUser(ctx context.Context, arg UpsertProjectDBUserParams) (ProjectDbUser, error) {
	row := q.db.QueryRow(ctx, upsertProjectDBUser,
		arg.ProjectID,
		arg.UserID,
		arg.OrgID,
		arg.RoleName,
		arg.ScramVerifier,
		arg.Access,
	)
	var i ProjectDbUser
	err := row.Scan(
		&i.ProjectID,
		&i.UserID,
		&i.OrgID,
		&i.RoleName,
		&i.ScramVerifier,
		&i.Access,
		&i.CreatedAt,
		&i.RotatedAt,
	)
	return i, err
}

